SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.NAME AS oblname, Имена_станций.ordnumb, Станции2017.YEAR, Станции2017.NUST, Станции2017.nr, Станции2017.E, Станции2017.EOTP, Станции2017.EURT, Станции2017.EUST, Станции2017.Q, Станции2017.TURT, Станции2017.TUST, Станции2017.B, Станции2017.GAZ, Доп_угли2017.gazpp, Станции2017.MAZUT, Станции2017.TORF, Станции2017.SLAN, Станции2017.PROCH, Станции2017.UGOL, Станции2017.DON, Станции2017.PODM, Станции2017.PECH, Доп_угли2017.intin, Доп_угли2017.vork, Станции2017.ARKT, Станции2017.KUZN, Доп_угли2017.kuzngd, Доп_угли2017.kuznt, Доп_угли2017.kuznss, Доп_угли2017.kuznun, Станции2017.URAL, Доп_угли2017.sver, Доп_угли2017.chel, Доп_угли2017.kizel, Станции2017.BASHK, Станции2017.KAZAH, Доп_угли2017.ekib, Доп_угли2017.maikub, Станции2017.KARAG, Станции2017.KAN, Доп_угли2017.nazar, Доп_угли2017.ibor, Доп_угли2017.berez, Доп_угли2017.per, Доп_угли2017.irbei, Доп_угли2017.kansk, Станции2017.TUNG, Доп_угли2017.jer, Доп_угли2017.karab, Станции2017.IRKUT, Доп_угли2017.azey, Доп_угли2017.mug, Доп_угли2017.cher, Станции2017.HAK, Станции2017.TUV, Станции2017.BUR, Доп_угли2017.gusin, Доп_угли2017.tugn, Доп_угли2017.okino, Станции2017.CHIT, Доп_угли2017.har, Доп_угли2017.urt, Доп_угли2017.tataur, Доп_угли2017.tarbag, Доп_угли2017.zab_kam, Станции2017.YAKUT, Доп_угли2017.neru, Доп_угли2017.zyryan, Доп_угли2017.pyak, Станции2017.AMUR, Доп_угли2017.rai, Доп_угли2017.erk, Станции2017.URG, Станции2017.USHUM, Станции2017.PRIM, Доп_угли2017.bikin, Доп_угли2017.razdol, Доп_угли2017.hankai, Станции2017.MAG, Станции2017.SAH, Станции2017.KAMCH, Станции2017.CHUKOT, Доп_угли2017.anad, Доп_угли2017.bering, Станции2017.QOTR, Станции2017.SNK, Станции2017.EWTP, Станции2017.NT, Станции2017.OBOR, Станции2017.VED, Станции2017.OBL, Станции2017.DEP, Станции2017.OES, Станции2017.ER, Станции2017.NUMB1120, Имена_станций.Ведомство AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.форэм, Имена_станций.GK, Станции2017.BE, имена_ГК.name AS namegk, имена_БЕ.name AS namebe, Города.Name AS Town, IIf([obor]=20 Or [obor]=90,"ГТУ",IIf([obor]=21 Or [obor]=91,"ПГУ",IIf([obor]=22,"Диз",IIf([obor]=23,"Дет","ПСУ")))) AS тип
FROM (((Имена_станций LEFT JOIN Города ON Имена_станций.codegor=Города.code) INNER JOIN (Имена_областей INNER JOIN (Имена_ОЭС INNER JOIN (Станции2017 LEFT JOIN Доп_угли2017 ON (Станции2017.YEAR=Доп_угли2017.YEAR) AND (Станции2017.NUMB1120=Доп_угли2017.NUMB1120)) ON Имена_ОЭС.oes=Станции2017.OES) ON Имена_областей.OBL=Станции2017.OBL) ON Имена_станций.NUMB=Станции2017.NUMB1120) LEFT JOIN имена_ГК ON Станции2017.GK=имена_ГК.code) LEFT JOIN имена_БЕ ON Станции2017.BE=имена_БЕ.code;
